            aOrbiterC = (aOrbiterC + aOrbiterF) + 0x951AD7B772D999D4ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterC) ^ 0x49354A1BD0991673ULL) ^ aOUSaltD[((aIndex + 160U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0xBFA8B66CDE617E31ULL), 13U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterI) + 0xF6E654116DBCDF59ULL;
