            aOrbiterG = RotL64((aOrbiterG * 0xCA7833E76D198BF1ULL), 43U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterE) + 0x33989A55B6C08999ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterA) ^ 0xA30FB2A53C9999E9ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x599857CCD636480DULL), 51U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterG) + 0x2465A82E72A7E698ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterH) ^ 0xD36BB9EC448180C3ULL) ^ aOUSaltH[(((511U - aIndex) + 359U)) & S_SALT1];
